  var AIRLINES = L.map(function (r) { return { iata: r[0], name: r[1], cc: r[2] }; });

  var BY_IATA = {}, AL_BY_IATA = {};
  AIRPORTS.forEach(function (a) { BY_IATA[a.iata] = a; });
  AIRLINES.forEach(function (a) { AL_BY_IATA[a.iata] = a; });

  /* Rank a query against the atlas. Exact IATA wins outright, then a
     city-prefix match, then a word-boundary hit, then anything. */
  function search(q, limit) {
    limit = limit || 8;
    q = String(q || '').trim().toLowerCase();
    if (!q) {
      return AIRPORTS.slice(0, limit);
    }
    var out = [];
    for (var i = 0; i < AIRPORTS.length; i++) {
      var a = AIRPORTS[i], s = -1;
      if (a.iata.toLowerCase() === q) s = 10000;
      else if (a.city.toLowerCase().indexOf(q) === 0) s = 5000;
      else if (a.name.toLowerCase().indexOf(q) === 0) s = 3000;
      else if (a.key.indexOf(' ' + q) >= 0) s = 1500;
      else if (a.key.indexOf(q) >= 0) s = 500;
      if (s > 0) out.push({ a: a, s: s + a.rank / 100 });
    }
    out.sort(function (x, y) { return y.s - x.s; });
    return out.slice(0, limit).map(function (o) { return o.a; });
  }

